\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
%\usetikzlibrary{arrows} %% Can be useful, not essential
%\usetikzlibrary{intersections} %% Can be useful, not essential
%\usepgfplotslibrary{fillbetween} %% Can be useful, not essential
\begin{document}
\pagestyle{empty} %% IMPORTANT
\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}
\begin{tikzpicture}
\begin{axis}[
%trig format plots=rad, %% Ensures radians for trig functions
tick style={draw=none},
tick label style={font=\footnotesize},
label style={font=\small},
legend style={font=\footnotesize},
tick style={draw=black},
axis line style = thick,
axis y line = center,
axis x line = middle,
axis equal,
% grid = both,
xmin = -5,
xmax = 5,
ymin = -5,
ymax = 5,
xtick = {-4,-2,...,4},
ytick = {-4,-2,...,4},
%xticklabels={,,},
%yticklabels={,,},
xlabel = $x$,
ylabel = {$y$},
xlabel style={right},
ylabel style={above}
]


\draw[color=deepskyblue, fill = deepskyblue, opacity = 0.2] (axis cs:10,10) --
(axis cs:10,-10) -- (axis cs:-10,-10) -- (axis cs:-10,10) -- (axis cs:10,10);

%Graphic
\addplot [domain=-6:6,samples=200, color=white, line width=1pt]{x^2} ;
\addplot [domain=-6:6,samples=200, color=deepskyblue, line width=1pt, dashed]{x^2} node[midway,pos=0.8, below right] {\color{black}{$y=x^2$}};


\draw[color=black, right] (axis cs:2,4) node {$y = x^2$};
\draw[color=deepskyblue] (axis cs:3.0,-3.0) node {$y \neq x^2$};

\end{axis}
\end{tikzpicture}
\end{document}

